/**
 * The Birthright
 * --------------
 * Esau comes in exhausted from the field and sells his birthright for a single bowl of lentil stew. Stage: a camp kitchen at midday, a hunter gasping at the door, a pot of red stew steaming, two brothers bargaining; a bright, ordinary moment with a heavy price.
 *
 * Palette 0x1a2a1a → 0x060402 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, house, tent, wheat, jar, cup, pillar, person } from './jacob-kit.js';

const BG = 0x1a2a1a;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1662644267, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -10, 0, -18, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* camp: a circle of tents */
    tent(W, group, 15.6, 0, -23.6, 1.10, 0xd8c8a0, W.r() * 6);
    tent(W, group, 14.9, 0, -5.9, 1.36, 0xc8b088, W.r() * 6);
    tent(W, group, 18.0, 0, -1.7, 1.04, 0xd8c8a0, W.r() * 6);
    tent(W, group, -14.3, 0, -5.0, 0.91, 0xd8c8a0, W.r() * 6);

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x1d2e1d, head: 0x213521 });

    jar(W, group, -0.9, 0, 2.7, );
    cup(W, group, -7.9, 0, -3.0, );

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x223722, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a2a1a, ry: 0.35, s: 1.07 });

    return W.finish();
}

export default { build };
